int[] memo = new int[n + 1];
Arrays.fill(memo, -1);

int solve(int i) {
    if (i <= 1) return i; // base case
    if (memo[i] != -1) return memo[i]; // already computed

    memo[i] = solve(i-1) + solve(i-2); // compute and store
    return memo[i];
}

